182	// the first occurrence again, the whole import goes through. Results keep
183	// manifest order — the first occurrence is created, every identical repeat
184	// and every already-registered record is a duplicate — and the registry ends
185	// up holding exactly one record per batch id.
186	func TestImportSucceedsWhenLateRecordMatchesFirstOccurrence(t *testing.T) {
