201		if len(out) != len(wantCreated) {
202			t.Fatalf("got %d results, want %d", len(out), len(wantCreated))
203		}
204		for i, want := range wantCreated {
205			if out[i].Created != want {
206				t.Errorf("record %d created=%v, want %v", i+1, out[i].Created, want)
207			}
208			if out[i].Batch.Batch != inputs[i].Batch {
209				t.Errorf("record %d batch=%q, want %q (manifest order)", i+1, out[i].Batch.Batch, inputs[i].Batch)
210			}
211		}
212		wantBatches := []Batch{
213			stored,
214			{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
215			{Batch: "B2", Product: "P-8", Quantity: 1, Unit: "box"},
216		}
217		if len(reg.Batches) != len(wantBatches) {
218			t.Fatalf("registry holds %d records, want one per batch id: %+v", len(reg.Batches), reg.Batches)
219		}
220		for i, want := range wantBatches {
221			if reg.Batches[i] != want {
222				t.Errorf("stored record %d = %+v, want %+v", i+1, reg.Batches[i], want)
223			}
224		}
225	}
